import java.util.*;

abstract class TrainingPlan {
    private String planName;

    public TrainingPlan(String planName) {
        this.planName = planName;
    }

    public String getPlanName() {
        return planName;
    }

    public abstract void attend(int minutes);
    public abstract String getProgress();
}

class TimePlan extends TrainingPlan {
    private int targetMinutes;
    private int attendedMinutes;

    public TimePlan(String planName, int targetMinutes) {
        super(planName);
        this.targetMinutes = targetMinutes;
        this.attendedMinutes = 0;
    }

    @Override
    public void attend(int minutes) {
        if (minutes > 0) {
            attendedMinutes += minutes;
            if (attendedMinutes > targetMinutes) {
                attendedMinutes = targetMinutes;
            }
        }
    }

    @Override
    public String getProgress() {
        return attendedMinutes + "/" + targetMinutes;
    }
}

class SessionPlan extends TrainingPlan {
    private int requiredSessions;
    private int completedSessions;

    public SessionPlan(String planName, int requiredSessions) {
        super(planName);
        this.requiredSessions = requiredSessions;
        this.completedSessions = 0;
    }

    @Override
    public void attend(int minutes) {
        if (minutes >= 30 && completedSessions < requiredSessions) {
            completedSessions++;
        }
    }

    @Override
    public String getProgress() {
        return completedSessions + "/" + requiredSessions;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String type = sc.next();
        String planName = sc.next();

        TrainingPlan plan;
        if (type.equals("TIME")) {
            int targetMinutes = sc.nextInt();
            plan = new TimePlan(planName, targetMinutes);
        } else {
            int requiredSessions = sc.nextInt();
            plan = new SessionPlan(planName, requiredSessions);
        }

        int firstAttend = sc.nextInt();
        int secondAttend = sc.nextInt();

        plan.attend(firstAttend);
        plan.attend(secondAttend);

        System.out.println(plan.getPlanName() + ":" + plan.getProgress());
    }
}

