import java.util.*;

abstract class TaskProcessor {
    protected int remainingTasks;
    protected int processedTasks;

    public TaskProcessor(int initialTasks) {
        this.remainingTasks = initialTasks;
        this.processedTasks = 0;
    }

    public abstract void processOneCycle();

    public void addTasks(int count) {
        if (count > 0) {
            remainingTasks += count;
        }
    }

    public void run(int cycles) {
        if (cycles <= 0) {
            return;
        }
        for (int i = 0; i < cycles; i++) {
            processOneCycle();
        }
    }

    public int getRemainingTasks() {
        return remainingTasks;
    }

    public int getProcessedTasks() {
        return processedTasks;
    }
}

class StandardProcessor extends TaskProcessor {
    private int capacity;

    public StandardProcessor(int initialTasks, int capacity) {
        super(initialTasks);
        this.capacity = capacity;
    }

    @Override
    public void processOneCycle() {
        if (capacity <= 0 || remainingTasks <= 0) {
            return;
        }
        int processedNow = Math.min(capacity, remainingTasks);
        remainingTasks -= processedNow;
        processedTasks += processedNow;
    }
}

class BurstProcessor extends TaskProcessor {
    private int capacity;
    private int cycleCount;

    public BurstProcessor(int initialTasks, int capacity) {
        super(initialTasks);
        this.capacity = capacity;
        this.cycleCount = 0;
    }

    @Override
    public void processOneCycle() {
        cycleCount++;
        if (capacity <= 0 || remainingTasks <= 0) {
            return;
        }

        int currentCapacity;
        if (cycleCount % 2 == 1) {
            currentCapacity = capacity;
        } else {
            currentCapacity = capacity + 1;
        }

        int processedNow = Math.min(currentCapacity, remainingTasks);
        remainingTasks -= processedNow;
        processedTasks += processedNow;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int standardInitial = sc.nextInt();
        int standardCapacity = sc.nextInt();
        int standardAdd = sc.nextInt();
        int standardCycles = sc.nextInt();

        int burstInitial = sc.nextInt();
        int burstCapacity = sc.nextInt();
        int burstAdd = sc.nextInt();
        int burstCycles = sc.nextInt();

        TaskProcessor p1 = new StandardProcessor(standardInitial, standardCapacity);
        TaskProcessor p2 = new BurstProcessor(burstInitial, burstCapacity);

        p1.addTasks(standardAdd);
        p1.run(standardCycles);

        p2.addTasks(burstAdd);
        p2.run(burstCycles);

        System.out.println(p1.getRemainingTasks());
        System.out.println(p1.getProcessedTasks());
        System.out.println(p2.getRemainingTasks());
        System.out.println(p2.getProcessedTasks());
    }
}

