public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int[] queue = new int[n];
        int f = -1;
        int l = -1;

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < m; i++) {
            String op = sc.next();

            if (op.equals("ENQ")) {
                int x = sc.nextInt();
                if (f == -1) {
                    f = 0;
                    l = 0;
                } else {
                    l = (l + 1) % n;
                }
                queue[l] = x;
            } else {
                if (f == l) {
                    f = -1;
                    l = -1;
                } else {
                    f = (f + 1) % n;
                }
            }

            if (f == -1) {
                out.append("EMPTY");
            } else {
                out.append(queue[f]);
            }

            if (i < m - 1) {
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

