public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        int front = -1;
        int rear = -1;
        int size = 0;
        int maxSize = 0;

        for (int i = 0; i < m; i++) {
            String op = sc.next();

            if (op.equals("ENQ")) {
                if (size == n) {
                    continue;
                }
                if (size == 0) {
                    front = 0;
                    rear = 0;
                } else {
                    rear = (rear + 1) % n;
                }
                size++;
                if (size > maxSize) {
                    maxSize = size;
                }
            } else if (op.equals("DEQ")) {
                if (size == 0) {
                    continue;
                }
                if (size == 1) {
                    front = -1;
                    rear = -1;
                    size = 0;
                } else {
                    front = (front + 1) % n;
                    size--;
                }
            }
        }

        System.out.println(maxSize);
    }
}

