    private int registeredMembers;

    public ClubBooking(String name, int slotCount) {
        super(name, slotCount);
        this.registeredMembers = 0;
    }

    public void registerMembers(int count) {
        if (count > 0 && registeredMembers + count <= slotCount) {
            registeredMembers += count;
        }
