        this.title = title;
        this.borrowed = borrowed;
    }

    public void borrow() {
        if (!borrowed) {
            borrowed = true;
        }
    }

    public void giveBack() {
        borrowed = false;
    }

    public String getStatus() {
        if (borrowed) {
            return title + ": borrowed";
        }
        return title + ": available";
    }
}

