        String title = sc.nextLine();
        String initialStatus = sc.nextLine();
        String action = sc.nextLine();

        boolean borrowed = initialStatus.equals("borrowed");
        Book book = new Book(title, borrowed);

        if (action.equals("borrow")) {
            book.borrow();
        } else if (action.equals("return")) {
            book.giveBack();
        }

        System.out.println(book.getStatus());
    }
}

