#include <stdio.h>

int isLeapYear(int y) {
    return (y % 4 == 0 && y % 400 != 0) || (y % 100 == 0);
}

int isValidDate(int m, int d, int y) {
    int maxDay;

    if (m < 1 || m > 12) {
        return 0;
    }
    if (d < 1) {
        return 0;
    }

    if (m == 2) {
        if (isLeapYear(y)) {
            maxDay = 29;
        } else {
            maxDay = 28;
        }
    } else if (m == 4 || m == 6 || m == 9 || m == 11) {
        maxDay = 30;
    } else {
        maxDay = 31;
    }

    return d <= maxDay;
}

int main(void) {
    int m, d, y;
    int i;

    for (i = 0; i < 3; i++) {
        scanf("%d %d %d", &m, &d, &y);
        if (isValidDate(m, d, y)) {
            printf("VALID\n");
        } else {
            printf("INVALID\n");
        }
    }

    return 0;
}

