import java.util.*;

class CallChain {
    public int mA(int x, int y) throws ArithmeticException {
        return mB(x, y);
    }

    public int mB(int x, int y) throws ArithmeticException {
        return mC(x, y);
    }

    public int mC(int x, int y) throws ArithmeticException {
        return mD(x, y);
    }

    public int mD(int x, int y) throws ArithmeticException {
        return x / y;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();

        CallChain chain = new CallChain();
        try {
            int result = chain.mA(x, y);
            System.out.println("Result: " + result);
        } catch (ArithmeticException e) {
            System.out.println("ArithmeticException caught in main");
        }
        System.out.println("End");
    }
}

